func NotifyExpired(code string) {
	hubsMu.Lock()
	h, ok := hubs[code]
	hubsMu.Unlock()
	if !ok {
		return
	}
	h.broadcast([]byte(`{"event":"session_expired"}`))
	h.mu.Lock()
	for conn := range h.clients {
		conn.Close()
	}
	h.mu.Unlock()
	h.cancel()
	hubsMu.Lock()
	delete(hubs, code)
	hubsMu.Unlock()
}

