function CreateSessionPage() {
  const [type, setType] = useState("quick_transfer");
  const [maxParticipants, setMaxParticipants] = useState(10);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const navigate = useNavigate();
  const toast = useToast();

  async function handleCreate() {
    setLoading(true);
    setError(null);
    try {
      const res = await api.createSession(type, type === "shared_workspace" ? maxParticipants : undefined);
      // owner_token itself lives in an HttpOnly cookie (unreadable from JS, by
      // design) and authorizes DELETE /sessions/:code server-side; this flag
      // just lets the room UI know to show the "end session" control.
      sessionStorage.setItem(`owner:${res.code}`, "1");

      // Generate the E2E encryption key entirely client-side. It is exported
      // into the URL fragment (never sent in a request) so SessionRoomPage
      // can pick it up on load and the server never learns it.
      const key = await generateSessionKey();
      const keyB64 = await exportKey(key);
      storeKey(res.code, keyB64);

      navigate(`/session/${res.code}#k=${keyB64}`);
    } catch (e) {
      setError(e.message);
      toast.error(e.message);
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="mx-auto max-w-xl">
      <h1 className="mb-1 text-2xl font-semibold text-slate-900 dark:text-slate-50">Start a session</h1>
      <p className="mb-8 text-slate-500 dark:text-slate-400">
        Pick a mode, get a link, share it. Everything is encrypted in your browser and self-destructs in 5 minutes.
      </p>

      <div className="mb-6 grid grid-cols-1 gap-3 sm:grid-cols-2">
        {MODES.map((mode) => (
          <button
            key={mode.id}
            onClick={() => setType(mode.id)}
            className={`rounded-xl border p-5 text-left transition hover:-translate-y-0.5 hover:shadow-md ${
              type === mode.id
                ? "border-brand-600 bg-brand-50 shadow-sm dark:border-brand-500 dark:bg-brand-500/10"
                : "border-slate-200 bg-white hover:border-slate-300 dark:border-slate-700 dark:bg-slate-900 dark:hover:border-slate-600"
            }`}
          >
            <div
              className={`mb-3 flex h-10 w-10 items-center justify-center rounded-lg ${
                type === mode.id ? "bg-brand-600 text-white" : "bg-slate-100 text-slate-500 dark:bg-slate-800 dark:text-slate-400"
              }`}
            >
              {mode.icon}
            </div>
            <div className="text-base font-semibold text-slate-800 dark:text-slate-100">{mode.title}</div>
            <div className="mt-1 text-sm leading-relaxed text-slate-500 dark:text-slate-400">{mode.description}</div>
          </button>
        ))}
      </div>

      {type === "shared_workspace" && (
        <label className="mb-6 block">
          <span className="text-sm text-slate-600 dark:text-slate-300">Max participants</span>
          <input
            type="number"
            min={2}
            max={100}
            value={maxParticipants}
            onChange={(e) => setMaxParticipants(Number(e.target.value))}
            className="mt-1 w-32 rounded-lg border border-slate-300 bg-white px-3 py-2 text-slate-900 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100"
          />
        </label>
      )}

      <div className="mb-6 flex items-start gap-2.5 rounded-lg border border-slate-200 bg-slate-50 px-3.5 py-2.5 text-xs text-slate-500 dark:border-slate-800 dark:bg-slate-900 dark:text-slate-400">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="mt-0.5 h-3.5 w-3.5 shrink-0">
          <rect x="5" y="11" width="14" height="9" rx="2" />
          <path d="M8 11V8a4 4 0 118 0v3" />
        </svg>
        <span>Files and text are encrypted on your device before upload. The decryption key lives only in the link you share — we never see it.</span>
      </div>

      {error && <p className="mb-4 text-sm text-red-600 dark:text-red-400">{error}</p>}

      <button
        onClick={handleCreate}
        disabled={loading}
        className="w-full rounded-lg bg-brand-600 py-3 font-medium text-white transition hover:bg-brand-700 disabled:opacity-60"
      >
        {loading ? "Creating…" : "Create session"}
      </button>

      <Link
        to="/join"
        className="mt-6 flex items-center justify-between gap-3 rounded-lg border border-slate-200 bg-white px-4 py-3 text-left transition hover:border-brand-300 hover:shadow-sm dark:border-slate-700 dark:bg-slate-900 dark:hover:border-brand-600"
      >
        <span className="text-sm text-slate-500 dark:text-slate-400">Have a code already?</span>
        <span className="flex items-center gap-1 text-sm font-semibold text-brand-600 dark:text-brand-400">
          Join a session
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="h-3.5 w-3.5">
            <path d="M5 12h14M13 6l6 6-6 6" />
          </svg>
        </span>
      </Link>
    </div>
  );
}

function shareLink() {
    const key = manualKeyInput || loadKey(code);
    return key ? `${window.location.origin}/session/${code}#k=${key}` : `${window.location.origin}/session/${code}`;
  }

async function handleJoin(e) {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      const { code, key } = parseInput(input);
      if (!code) throw new Error("Enter an access code or paste a shared link");
      await api.getSession(code); // validate it exists before navigating
      if (key) {
        storeKey(code, key);
        navigate(`/session/${code}#k=${key}`);
      } else {
        navigate(`/session/${code}`);
      }
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  }

async function copyLink() {
    try {
      await navigator.clipboard.writeText(shareLink());
      toast.success("Link copied — includes the decryption key");
    } catch {
      toast.error("Couldn't copy — copy the link from the address bar instead");
    }
  }
